        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0:
            a = radii[i]
            c = radii[j]
            if a is not None and c is not None and isfinite(a) and isfinite(c) and a > 0 and c > 0:
