def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    totals = [0.0 for i in range(n)]
    weights = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0:
            a = radii[i]
            c = radii[j]
            x = chi[i]
            y = chi[j]
            if a is not None and c is not None and x is not None and y is not None and isfinite(a) and isfinite(c) and isfinite(x) and isfinite(y) and a > 0 and c > 0:
                w = exp(-6.0 * max(0.0, d / (a + c) - 1.0))
                totals[i] = totals[i] + w * (y - x)
                weights[i] = weights[i] + w
    values = [totals[i] / weights[i] for i in range(n) if weights[i] > 0]
    if not values:
        return 0.0
    mean = sum(values) / len(values)
    return sqrt(sum([(x - mean) ** 2 for x in values]) / len(values))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    counts = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0:
            a = radii[i]
            c = radii[j]
            if a is not None and c is not None and isfinite(a) and isfinite(c) and a > 0 and c > 0 and d <= 1.5 * (a + c):
                counts[i] = counts[i] + 1.0
    valid = [i for i in range(n) if radii[i] is not None and isfinite(radii[i]) and radii[i] > 0]
    return sum([float(counts[i] == 0) for i in valid]) / len(valid) if valid else 0.0

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        z = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and z is not None and isfinite(fraction) and isfinite(z) and fraction > 0:
            total = total + fraction * z
            weight = weight + fraction
    return total / (weight * v) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if n == 0 or matrix is None:
        return 0.0
    lattice = np.asarray(matrix)
    if lattice.shape != (3, 3) or not np.all(np.isfinite(lattice)):
        return 0.0
    edges = s.get('neighbors') or []
    total = 0.0
    count = 0
    for i in range(n):
        origin = sites[i].get('frac_coords')
        if origin is not None and len(origin) == 3:
            distances = [b['distance_A'] for b in edges if b.get('i') == i and b.get('distance_A') is not None and isfinite(b['distance_A']) and b['distance_A'] > 0]
            if distances:
                cutoff = 1.25 * min(distances)
                shell = [b for b in edges if b.get('i') == i and b.get('j') is not None and 0 <= b['j'] < n and b.get('distance_A') is not None and isfinite(b['distance_A']) and 0 < b['distance_A'] <= cutoff and b.get('image') is not None and len(b['image']) == 3 and sites[b['j']].get('frac_coords') is not None and len(sites[b['j']]['frac_coords']) == 3]
                if shell:
                    vectors = np.asarray([np.matmul(np.asarray([sites[b['j']]['frac_coords'][k] + b['image'][k] - origin[k] for k in range(3)]), lattice) / b['distance_A'] for b in shell])
                    if np.all(np.isfinite(vectors)):
                        tensor = np.matmul(vectors.T, vectors)
                        trace = np.trace(tensor)
                        if trace > 0:
                            tensor = tensor / trace
                            value = (3.0 * np.trace(np.matmul(tensor, tensor)) - 1.0) / 2.0
                            total = total + max(0.0, min(1.0, float(value)))
                            count = count + 1
    return total / count if count else 0.0
